function dashboardLanguage() {
  return document.documentElement.lang === 'en' ? 'en' : 'cs';
}

function dashboardText(czech) {
  return dashboardLanguage() === 'en' && Object.hasOwn(DASHBOARD_ENGLISH, czech)
    ? DASHBOARD_ENGLISH[czech] : czech;
}

// Only literal source fragments form the lookup key. Interpolated customer data is inserted afterwards.
function dashboardMessage(parts, ...values) {
  const key = parts.map((part, index) => part + (index < values.length ? `{${index}}` : '')).join('');
  const pattern = dashboardText(key);
  return pattern.replace(/\{(\d+)\}/g, (match, index) => Number(index) < values.length ? String(values[Number(index)]) : match);
}

// The API's own error templates are matched before translating. Captured details stay unchanged.
const DASHBOARD_API_ERROR_KEYS = ["Počet osob musí být od {0} do {1}.", "Rezervaci lze vytvořit maximálně {0} dní dopředu.", "Rezervace musí celá proběhnout mezi {0} a {1}.", "Čas zasahuje do blokace: {0}"];
function dashboardApiError(value) {
  const text = String(value ?? '');
  if (dashboardLanguage() !== 'en') return text;
  if (Object.hasOwn(DASHBOARD_ENGLISH, text)) return DASHBOARD_ENGLISH[text];
  for (const key of DASHBOARD_API_ERROR_KEYS) {
    const fragments = key.split(/\{\d+\}/);
    const pattern = fragments.map(part => part.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('([\\s\\S]*?)');
    const match = new RegExp('^' + pattern + '$').exec(text);
    if (match) return dashboardText(key).replace(/\{(\d+)\}/g, (_, index) => match[Number(index) + 1]);
  }
  return text;
}

function dashboardFoodCategory(value) {
  const names = { Pizza: 'Pizza', 'Předkrm': 'Starter', 'Hlavní jídlo': 'Main course', 'Těstoviny': 'Pasta', Dezert: 'Dessert', 'Sladká jídla': 'Sweet dishes', 'Nápoj': 'Drink' };
  if (!value) return dashboardText('Bez kategorie');
  return dashboardLanguage() === 'en' && Object.hasOwn(names, value) ? names[value] : value;
}

function dashboardLocale() {
  return dashboardLanguage() === 'en' ? 'en-GB' : 'cs-CZ';
}

function changeDashboardLanguage(select) {
  const previous = dashboardLanguage();
  const next = select.value;
  if (!['cs', 'en'].includes(next) || next === previous) { select.value = previous; return; }
  const live = select.dataset?.languageMode === 'live';
  // Reload only after confirmation, so in-flight requests and unsaved forms are not silently lost.
  if (!live && !window.confirm(dashboardText('Změnit jazyk? Stránka se obnoví a neuložené změny se zahodí.'))) {
    select.value = previous;
    return;
  }
  try {
    localStorage.setItem('dashboardLanguage', next);
  } catch {
    select.value = previous;
    window.alert(dashboardText('Jazyk se nepodařilo uložit. Povol úložiště prohlížeče a zkus to znovu.'));
    return;
  }
  if (live) {
    document.documentElement.lang = next;
    applyDashboardTranslations();
    document.querySelectorAll('[data-dashboard-language]').forEach(item => { item.value = next; });
    document.dispatchEvent(new Event('dashboardlanguagechange'));
    return;
  }
  location.reload();
}

const dashboardOriginalText = new WeakMap();
const dashboardOriginalAttributes = new WeakMap();

function initializeDashboardLanguage() {
  let language = 'cs';
  try {
    if (localStorage.getItem('dashboardLanguage') === 'en') language = 'en';
  } catch { /* Czech remains available when storage is blocked. */ }
  document.documentElement.lang = language;
  document.querySelectorAll('[data-dashboard-language]').forEach(select => { select.value = language; });
  applyDashboardTranslations();
}

function applyDashboardTranslations() {
  // Dashboard calls this only at boot, before any restaurant or guest data is inserted.
  // The invitation page can reapply cached source text without reloading its one-use auth link.
  document.querySelectorAll('[data-dashboard-i18n]').forEach(element => {
    for (const node of element.childNodes) {
      if (node.nodeType !== 3) continue;
      if (!dashboardOriginalText.has(node)) dashboardOriginalText.set(node, node.textContent);
      const original = dashboardOriginalText.get(node);
      const key = original.trim().replace(/\s+/g, ' ');
      if (Object.hasOwn(DASHBOARD_ENGLISH, key)) {
        node.textContent = original.replace(original.trim(), dashboardText(key));
      }
    }
    if (!dashboardOriginalAttributes.has(element)) {
      dashboardOriginalAttributes.set(element, Object.fromEntries(['aria-label', 'title', 'placeholder', 'alt'].map(name => [name, element.getAttribute(name)])));
    }
    for (const attribute of ['aria-label', 'title', 'placeholder', 'alt']) {
      const value = dashboardOriginalAttributes.get(element)[attribute];
      if (value && Object.hasOwn(DASHBOARD_ENGLISH, value)) element.setAttribute(attribute, dashboardText(value));
    }
  });
}

initializeDashboardLanguage();
